/** Bounded LIFO stack with fixed capacity. */
export class Stack<T> {
  private items: T[] = [];

  constructor(private readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
  }

  /** Push an item; throws on overflow. */
  push(item: T): void {
    if (this.items.length >= this.capacity) {
      throw new RangeError("stack overflow");
    }
    this.items.push(item);
  }

  /** Remove and return the top item; throws on underflow. */
  pop(): T {
    if (this.items.length === 0) {
      throw new RangeError("stack underflow");
    }
    return this.items.pop() as T;
  }

  /** Return the top item without removing it; throws if empty. */
  peek(): T {
    if (this.items.length === 0) {
      throw new RangeError("stack is empty");
    }
    return this.items[this.items.length - 1];
  }

  /** Current number of items. */
  size(): number {
    return this.items.length;
  }
}

/** Fixed-capacity FIFO ring buffer. */
export class Ring<T> {
  private buf: (T | undefined)[];
  private head = 0;
  private count = 0;

  constructor(private readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    this.buf = new Array<T | undefined>(capacity);
  }

  /** Enqueue at the tail; throws on overflow. */
  enqueue(item: T): void {
    if (this.count >= this.capacity) {
      throw new RangeError("ring overflow");
    }
    this.buf[(this.head + this.count) % this.capacity] = item;
    this.count += 1;
  }

  /** Dequeue from the head; throws on underflow. */
  dequeue(): T {
    if (this.count === 0) {
      throw new RangeError("ring underflow");
    }
    const item = this.buf[this.head] as T;
    this.buf[this.head] = undefined;
    this.head = (this.head + 1) % this.capacity;
    this.count -= 1;
    return item;
  }

  /** Return the head item without removing it; throws if empty. */
  peek(): T {
    if (this.count === 0) {
      throw new RangeError("ring is empty");
    }
    return this.buf[this.head] as T;
  }

  /** Current number of items. */
  size(): number {
    return this.count;
  }
}

